use vstd::prelude::*;

verus! {

fn numpy_append(arr: Vec<f32>, values: Vec<f32>) -> (result: Vec<f32>)
    ensures
        result.len() == arr.len() + values.len(),
        forall|i: int|
            0 <= i < arr.len() ==> result[i] == arr[i],
        forall|j: int|
            0 <= j < values.len() ==> result[arr.len() + j] == values[j],
{
    let mut result: Vec<f32> = Vec::new();
    let arr_len = arr.len();
    let values_len = values.len();

    let mut i: usize = 0;
    while i < arr_len
        invariant
            result.len() == i,
            forall|k: int| 0 <= k < i as int ==> result[k] == arr[k],
    {
        result.push(arr[i]);
        i += 1;
    }

    let mut j: usize = 0;
    while j < values_len
        invariant
            result.len() == arr_len + j,
            // arr part preserved
            forall|k: int| 0 <= k < arr_len as int ==> result[k] == arr[k],
            // values part built so far
            forall|k: int| 0 <= k < j as int ==> result[arr_len + k] == values[k],
    {
        result.push(values[j]);
        j += 1;
    }

    result
}

} // verus!